  let col = COLS.findIndex((c) => x <= c.x1 + 9);
  let row = ROWS.findIndex((r) => y <= r.y1 + 9);
  if (col < 0) col = 5;
  if (row < 0) row = 3;
  return GROUND_TINTS[row][col];
}

export function streetNameAt(x, y) {
  let best = null;
  let bestD = 15;
  for (const a of AVENUES) {
